INSERT INTO clinic_faqs (topic, question, answer, is_active)
VALUES
  ('General', 'คลินิกมีกี่สาขา', 'เอริกาคลินิกมีสาขาเดียวค่ะ ตั้งอยู่ซอยพหลโยธิน 24 ใกล้เซ็นทรัลลาดพร้าว กรุงเทพฯ ยังไม่มีสาขาต่างจังหวัดนะคะ', true),
  ('General', 'คุณหมอมีประสบการณ์กี่ปี เชี่ยวชาญด้านไหน', 'คุณหมอเจ้าของคลินิกมีประสบการณ์มากกว่า 9 ปี เชี่ยวชาญด้านเสริม/แก้ไขจมูกโดยเฉพาะ รวมถึงหัตถการปรับรูปหน้าและดูแลผิวค่ะ', true),
  ('General', 'ทำหัตถการเจ็บไหม มียาชาให้หรือเปล่า', 'ทุกหัตถการ (ฉีดฟิลเลอร์ โบท็อกซ์ Ultraformer) มียาชาแบบทาและฉีดเฉพาะจุดให้ก่อนทำเสมอ ไม่มีค่าใช้จ่ายเพิ่มเติมค่ะ ระหว่างทำอาจรู้สึกตึงหรือจี๊ดเล็กน้อยแต่ไม่ปวดมากค่ะ', true),
  ('Payment', 'จ่ายบัตรเครดิตได้ไหม ผ่อนชำระได้หรือเปล่า', 'รับชำระบัตรเครดิตค่ะ ยอดต่ำกว่า 10,000 บาทมีค่าธรรมเนียมเพิ่ม 3% ส่วนยอดตั้งแต่ 10,000 บาทขึ้นไปไม่มีค่าธรรมเนียมค่ะ ปัจจุบันคลินิกยังไม่มีบริการผ่อนชำระ ขึ้นอยู่กับเงื่อนไขบัตรเครดิตของลูกค้าเองค่ะ', true),
  ('Booking', 'ยกเลิกหรือเลื่อนนัดได้ไหม', 'เลื่อนนัดได้ตามความสะดวกค่ะ แต่หากต้องการยกเลิก รบกวนแจ้งล่วงหน้าอย่างน้อย 3 วัน เพื่อเปิดคิวให้ลูกค้าท่านอื่นนะคะ', true),
  ('Botox', 'ฉีดโบท็อกซ์แล้วอยู่ได้นานแค่ไหน', 'ผลลัพธ์จะเริ่มเห็นภายใน 1-2 สัปดาห์หลังฉีด และอยู่ได้ประมาณ 4-6 เดือนค่ะ แต่ละคนอาจอยู่ได้ไม่เท่ากันขึ้นอยู่กับการเผาผลาญของร่างกายค่ะ', true),
  ('Filler', 'ฟิลเลอร์แต่ละยี่ห้อ (Neuramis / E.P.T.Q. / Restylane) ต่างกันอย่างไร', 'Neuramis (กล่องดำ) เนื้อนุ่ม ปั้นทรงง่าย คุ้มค่าสำหรับจุดที่ใช้ปริมาณน้อย, E.P.T.Q. ให้วอลลุ่มและอยู่ทนกว่า เหมาะจุดที่ต้องใช้ปริมาณเยอะ, Restylane เป็นฟิลเลอร์พรีเมียมสวีเดน อยู่ได้นานที่สุด คุณหมอจะช่วยแนะนำให้เหมาะกับตำแหน่งและงบประมาณค่ะ', true),
  ('Filler', 'ฟิลเลอร์ยกหางตาทำได้ไหม ใช้กี่ CC', 'ทำได้ค่ะ คุณหมอจะฉีดบริเวณขมับ/เหนือคิ้วเพื่อดันให้หางตายกขึ้น ช่วยให้ตาดูโตและสดใสขึ้น โดยทั่วไปใช้ประมาณข้างละ 0.5-1cc ทั้งนี้คุณหมอจะประเมินหน้าก่อนฉีดจริงค่ะ', true),
  ('Filler', 'เพิ่งฉีดฟิลเลอร์มา อยากเติมเพิ่มต้องรอนานไหม', 'แนะนำเว้นระยะอย่างน้อย 7 วันก่อนเติมเพิ่มค่ะ เพื่อรอให้อาการบวมยุบตัวก่อนและป้องกันการอักเสบ', true),
  ('Surgery', 'เตรียมตัวก่อนทำศัลยกรรมอย่างไรบ้าง', 'แจ้งโรคประจำตัว ยาที่ทานประจำ และประวัติแพ้ยาให้คุณหมอทราบก่อนค่ะ งดยา/วิตามินที่มีผลต่อการแข็งตัวของเลือดประมาณ 1-2 สัปดาห์ก่อนทำ งดบุหรี่และแอลกอฮอล์ และพักผ่อนให้เพียงพอค่ะ', true),
  ('Surgery', 'เคสแก้จมูก ราคาต่างจากเสริมใหม่อย่างไร รับรองผลลัพธ์ตามที่ต้องการได้ไหม', 'เคสแก้จะบวกเพิ่มจากราคาโปรโมชั่นเสริมใหม่ 5,000 บาท และเนื่องจากเป็นเคสแก้ไข คุณหมอจำเป็นต้องประเมินสภาพซิลิโคนเดิมและเนื้อจมูกหน้างานก่อน จึงยังไม่สามารถยืนยันผลลัพธ์ที่แน่นอนจากการดูรูปเพียงอย่างเดียวได้ค่ะ', true),
  ('Weight Loss', 'ปากกาลดน้ำหนักแบบรายครั้งใช้เข็มร่วมกับคนอื่นหรือเปล่า สะอาดปลอดภัยไหม', 'ไม่มีการใช้เข็มร่วมกันค่ะ ทำความสะอาดและเตรียมอุปกรณ์ใหม่ทุกครั้งก่อนทำหัตถการ ยาของแท้ 100% ตรวจสอบได้ค่ะ', true),
  ('Weight Loss', 'ใช้ Mounjaro แล้วปกติลดน้ำหนักได้กี่กิโลต่อสัปดาห์', 'โดยเฉลี่ยลดได้ประมาณ 1-2 กก./สัปดาห์ค่ะ คุณหมอจะควบคุมโดสไม่ให้ลดเร็วเกินไปเพื่อความปลอดภัย หากเริ่มหิวบ่อยหลังใช้ไปหลายสัปดาห์ คุณหมออาจปรับโดสหรือแนะนำการทานอาหารเพิ่มเติมค่ะ', true),
  ('Aftercare', 'ทำเลเซอร์/หัตถการแล้วรู้สึกยิบๆ ร้อนๆ ผิดปกติไหม', 'เป็นปฏิกิริยาปกติของผิวที่กำลังฟื้นตัวหลังได้รับพลังงานค่ะ อาการจะค่อยๆ ดีขึ้นเอง แนะนำทามอยส์เจอไรเซอร์/ครีมบำรุงตามคำแนะนำของคุณหมอ หลีกเลี่ยงแดดจัดและทากันแดดสม่ำเสมอ หากอาการไม่ดีขึ้นหรือรุนแรงขึ้น รบกวนแจ้งแอดมินเพื่อให้คุณหมอตรวจดูอาการค่ะ', true);
INSERT INTO clinic_services (category, name, description, target_audience, cautions, base_price, is_active)
VALUES
  ('Skin Tightening', 'Ultraformer III 200 shots', 'หัตถการยกกระชับผิวหน้าด้วยคลื่นอัลตราซาวด์ HIFU ลงลึกถึงชั้น SMAS ช่วยลดหย่อนคล้อยเล็กน้อย', 'ผู้ที่มีผิวหย่อนคล้อยเล็กน้อย ต้องการกระชับกรอบหน้า', 'ราคาส่งเสริมการขาย อาจเปลี่ยนแปลงตามช่วงโปรโมชั่น โปรดยืนยันราคากับแอดมินก่อนจอง', 4444, true),
  ('Skin Tightening', 'Ultraformer III 300 shots', 'หัตถการยกกระชับผิวหน้าด้วยคลื่นอัลตราซาวด์ HIFU สำหรับผิวหย่อนคล้อยระดับปานกลาง', 'ผู้ที่มีผิวหย่อนคล้อยปานกลาง', 'ราคาส่งเสริมการขาย อาจเปลี่ยนแปลงตามช่วงโปรโมชั่น โปรดยืนยันราคากับแอดมินก่อนจอง', 6900, true),
  ('Skin Tightening', 'Ultraformer III 400 shots', 'หัตถการยกกระชับผิวหน้าด้วยคลื่นอัลตราซาวด์ HIFU ครอบคลุมกรอบหน้าและเหนียง เห็นผลบางส่วนทันทีหลังทำ เต็มที่ในประมาณ 1 เดือน อยู่ได้ราว 6 เดือน', 'ผู้ที่มีผิวหย่อนคล้อยมาก ต้องการเก็บกรอบหน้าและเหนียง', 'มียาชาทาให้ก่อนทำ แนะนำเว้นระยะ 6-8 เดือนก่อนทำซ้ำหากเคยทำมาก่อน ราคาส่งเสริมการขายอาจเปลี่ยนแปลง โปรดยืนยันกับแอดมินก่อนจอง', 8000, true),
  ('Skin Booster', 'Juvelook ใต้ตา', 'สกินบูสเตอร์ฉีดเติมเต็มบริเวณใต้ตา ช่วยแก้ปัญหาใต้ตาคล้ำและร่องลึก', 'ผู้ที่มีปัญหาใต้ตาคล้ำ ร่องใต้ตาลึก', 'ราคาส่งเสริมการขาย อาจเปลี่ยนแปลงตามช่วงโปรโมชั่น โปรดยืนยันราคากับแอดมินก่อนจอง', 3000, true),
  ('Bundle', 'โปรมิกซ์แอนด์แมทช์ เลือก 1 หัตถการ', 'โปรโมชั่นให้ลูกค้าเลือกทำได้ 1 รายการจากลิสต์ที่คลินิกกำหนด (เช่น ฟิลเลอร์บางรุ่น) ในราคาพิเศษ เหมาะสำหรับลูกค้าใหม่ที่ต้องการทดลองบริการ', 'ลูกค้าใหม่ที่ต้องการทดลองราคาประหยัด', 'รายการที่เลือกได้ขึ้นอยู่กับโปรโมชั่นปัจจุบัน โปรดสอบถามแอดมินว่ารายการใดร่วมโปรอยู่', 3333, true),
  ('Weight Loss', 'ปากกาลดน้ำหนัก Mounjaro 10mg (เหมาแท่ง)', 'ปากกาลดน้ำหนักโดสสูง 10mg แบบเหมาแท่ง สำหรับผู้ที่ต้องการโดสสูงกว่ามาตรฐานภายใต้การดูแลของคุณหมอ', 'ผู้ที่เคยใช้โดส 2.5mg มาแล้วและคุณหมอประเมินว่าต้องการโดสสูงขึ้น', 'ต้องสอบถามโรคประจำตัวและประวัติแพ้ยาก่อนเริ่มใช้ ควบคุมโดยแพทย์', 21000, true);
